# calculate counts and 4/8-connected components for test foreground
from collections import deque,Counter
print(Counter(v for row in T for v in row))
for conn in [4,8]:
    unseen={(r,c) for r in range(len(T)) for c in range(len(T[0])) if T[r][c]==6}
    comps=[]
    while unseen:
        st=[unseen.pop()]; comp=[]
        while st:
            x=st.pop(); comp.append(x)
            r,c=x
            for dr in [-1,0,1]:
                for dc in [-1,0,1]:
                    if (dr,dc)==(0,0) or (conn==4 and abs(dr)+abs(dc)!=1): continue
                    y=(r+dr,c+dc)
                    if y in unseen: unseen.remove(y); st.append(y)
        comps.append(comp)
    print(conn,[(len(c), min(r for r,x in c),max(r for r,x in c),min(x for r,x in c),max(x for r,x in c)) for c in comps])
